 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    floor = Counter(v for row in grid for v in row).most_common(1)[0][0]

    row_lines = []
    for r, row in enumerate(grid):
        color, n = Counter(row).most_common(1)[0]
        if color != floor and n >= 0.75 * w:
            row_lines.append((r, color))
    col_lines = []
    for c in range(w):
        color, n = Counter(grid[r][c] for r in range(h)).most_common(1)[0]
        if color != floor and n >= 0.75 * h:
            col_lines.append((c, color))

    if len(row_lines) < 2 or len(col_lines) < 2:
        return [[floor]]
    lattice = row_lines[0][1]

    # The non-lattice colors mark the corners of the portion of the lattice
    # that represents the output. Ignore extra unmarked grid lines outside it.
    marked_rows = []
    marked_cols = []
    for ri, (r, _) in enumerate(row_lines):
        for ci, (c, _) in enumerate(col_lines):
            if grid[r][c] not in (floor, lattice):
                marked_rows.append(ri)
                marked_cols.append(ci)
    if not marked_rows:
        return [[floor]]
    rlo, rhi = min(marked_rows), max(marked_rows)
    clo, chi = min(marked_cols), max(marked_cols)

    out = []
    for ri in range(rlo, rhi):
        out_row = []
        r1, r2 = row_lines[ri][0], row_lines[ri + 1][0]
        for ci in range(clo, chi):
            c1, c2 = col_lines[ci][0], col_lines[ci + 1][0]
            corners = [grid[r1][c1], grid[r1][c2], grid[r2][c1], grid[r2][c2]]
            markers = Counter(v for v in corners if v not in (floor, lattice))
            if markers and markers.most_common(1)[0][1] == 4:
                out_row.append(markers.most_common(1)[0][0])
            else:
                out_row.append(floor)
        out.append(out_row)
    return out
